window.__auto = {
  lead() { const s = window.__ensemble.getState(); return (s.chats.find(c => c.id === s.chatId)?.leadId) || s.settings.leadId || s.accounts.find(a => a.enabled)?.id },
  want: null,
  patch(goal, loops) {
    const st = window.__ensemble; const A = window.__auto;
    const cur = st.getState().chats.find(c => c.id === A.chatId) || {};
    A.want = { goal: goal === undefined ? (A.want ? A.want.goal : cur.goal) : goal, loops: loops === undefined ? (A.want ? A.want.loops : cur.loops) : loops };
    A.apply();
    if (!A.sub) A.sub = st.subscribe(s => { const c = s.chats.find(c => c.id === A.chatId); if (c && A.want && (c.goal !== A.want.goal || c.loops !== A.want.loops)) setTimeout(A.apply, 0); });
  },
  apply() {
    const A = window.__auto;
    window.__ensemble.setState(s => ({ chats: s.chats.map(c => c.id === A.chatId && (c.goal !== A.want.goal || c.loops !== A.want.loops) ? { ...c, goal: A.want.goal, loops: A.want.loops } : c) }));
  },
  goal(extra) {
    const now = Date.now();
    return Object.assign({ id: 'g1', text: 'Get the whole test suite green and the build passing on Windows and Linux', doneWhen: 'pnpm test passes with no skipped tests and CI is green', status: 'active', round: 2, maxRounds: 12, deadline: now + 47 * 60000, check: 'fresh', createdAt: now - 14 * 60000, note: 'Still missing: two date tests fail on Linux (timezone), and CI has not run yet.', log: [ { round: 0, ts: now - 9 * 60000, met: false, note: 'Seven tests fail in src/date and src/sync.' }, { round: 1, ts: now - 3 * 60000, met: false, note: 'Sync tests pass now. Two date tests still fail on Linux.' } ] }, extra || {});
  },
  loops() {
    const now = Date.now();
    return [
      { id: 'l1', prompt: 'Check the deploy and tell me when it is live', to: window.__auto.lead(), every: 15 * 60000, status: 'active', runs: 3, maxRuns: 10, until: 'the site answers on the new version', nextAt: now + 252000, lastAt: now - 648000, last: 'Still building: 4 of 6 steps done', createdAt: now - 3600000 },
      { id: 'l2', prompt: 'Look through new issues and sort them by how urgent they are', to: window.__auto.lead(), every: null, status: 'paused', runs: 5, nextAt: null, last: 'Sorted 3 new issues, one marked urgent', createdAt: now - 7200000 },
    ];
  },
};
return 'setup';

const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/) || find(/^Let /);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ') + ' | onboarded=' + window.__ensemble.getState().settings.onboarded;

const s = window.__ensemble.getState();
await s.send('Get the whole test suite green and the build passing on Windows and Linux');
return 'chat ' + window.__ensemble.getState().chatId;

const st = window.__ensemble; const s = st.getState();
window.__auto.chatId = s.chatId;
window.__auto.addItems = (tag) => {
const k = window.__auto.chatId + ':' + window.__auto.lead();
const now = Date.now(); let n = 0;
const id = () => 'fake-' + tag + (n++);
const mk = (o, ago) => Object.assign({ id: id(), ts: now - ago * 60000 }, o);
const add = [
  mk({ kind: 'auto', of: 'goal', event: 'set', ref: 'g1', title: 'Goal set', text: 'Get the whole test suite green and the build passing on Windows and Linux. Done when pnpm test passes with no skipped tests and CI is green.' }, 14),
  mk({ kind: 'assistant', text: 'I ran the suite: **7 tests fail**, in `src/date` and `src/sync`. Fixing the sync ones first.' }, 13),
  mk({ kind: 'turn', status: 'done', durationMs: 240000 }, 10),
  mk({ kind: 'auto', of: 'goal', event: 'check', ref: 'g1', title: 'Check 1 of 12: not there yet', text: 'Sync tests pass now. Two date tests still fail on Linux: formatDay and parseRange assume the local timezone.', round: 1, max: 12 }, 9),
  mk({ kind: 'assistant', text: 'Both date helpers now take the timezone from the caller. Running the suite on the Linux image next.' }, 8),
  mk({ kind: 'turn', status: 'done', durationMs: 300000 }, 4),
  mk({ kind: 'auto', of: 'loop', event: 'run', ref: 'l1', title: 'Run 3 of 10', text: 'Check the deploy and tell me when it is live', round: 3, max: 10 }, 3.5),
  mk({ kind: 'assistant', text: 'Still building: 4 of 6 steps done. I will look again at the next run.' }, 3.4),
  mk({ kind: 'turn', status: 'done', durationMs: 20000 }, 3.3),
  mk({ kind: 'auto', of: 'loop', event: 'paused', ref: 'l2', title: 'Loop paused', text: 'You paused "Look through new issues".' }, 3.2),
  mk({ kind: 'auto', of: 'goal', event: 'blocked', ref: 'g1', title: 'Needs you', text: 'CI needs a token to publish the Linux build. Add LINUX_DEPLOY_TOKEN to the repository secrets, then say carry on.' }, 3),
  mk({ kind: 'auto', of: 'goal', event: 'resumed', ref: 'g1', title: 'Goal resumed' }, 2),
  mk({ kind: 'auto', of: 'goal', event: 'met', ref: 'g1', title: 'Goal met after 3 rounds', text: 'A fresh checker ran pnpm test (412 passed, 0 skipped) and saw CI green on both systems.' }, 1),
  mk({ kind: 'auto', of: 'loop', event: 'done', ref: 'l1', title: 'Loop ended after 4 runs', text: 'The site answers on the new version.' }, 0.5),
];
st.setState(x => ({ items: { ...x.items, [k]: [...(x.items[k] || []), ...add] } }));
return k;
};
const k = window.__auto.addItems('a');
window.__auto.patch(window.__auto.goal(), window.__auto.loops());
const chat = st.getState().chats.find(c => c.id === s.chatId);
return 'items for ' + k + ': ' + st.getState().items[k].length + ' | goal=' + !!chat.goal + ' loops=' + (chat.loops||[]).length + ' | bar=' + !!document.querySelector('[data-auto-bar]');

const st = window.__ensemble; const now = Date.now();
const base = st.getState().chats.find(c => c.id === window.__auto.chatId);
const fake = (id, title, extra) => Object.assign({}, base, { id, title, createdAt: now - 3600000, updatedAt: now - 600000, goal: null, loops: [], snippet: '' }, extra);
st.setState(s => ({ chats: [
  ...s.chats,
  fake('fake-a', 'Pricing page and checkout', { goal: window.__auto.goal({ id: 'ga', text: 'Checkout works end to end with a test card', status: 'blocked', round: 4, note: 'Needs the Stripe test key', deadline: null }) }),
  fake('fake-b', 'Morning inbox sweep', { loops: [ Object.assign(window.__auto.loops()[0], { id: 'lb', prompt: 'Sort my inbox and draft replies to anything urgent', every: 3600000, nextAt: now + 38 * 60000, runs: 6, maxRuns: null, until: '' }) ] }),
  fake('fake-c', 'Docs rewrite', { goal: window.__auto.goal({ id: 'gc', text: 'Every page of the docs uses the new API names', status: 'paused', round: 1, note: '', deadline: null }) }),
] }));
window.__auto.patch(window.__auto.goal({ checking: true })); return 'chats: ' + st.getState().chats.length;
